/*---
description: NFD agrees with Node for every code point U+0D0000 through U+0DFFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [3117048261, 3467145669, 1514602949, 896328133, 2562707909, 3192424901, 2738784709, 2168154565, 665539013, 816196037, 63156677, 430424517, 668359109, 3350954437, 628607429, 399081925];
const blocks = ["NFD U+0D0000-U+0D0FFF", "NFD U+0D1000-U+0D1FFF", "NFD U+0D2000-U+0D2FFF", "NFD U+0D3000-U+0D3FFF", "NFD U+0D4000-U+0D4FFF", "NFD U+0D5000-U+0D5FFF", "NFD U+0D6000-U+0D6FFF", "NFD U+0D7000-U+0D7FFF", "NFD U+0D8000-U+0D8FFF", "NFD U+0D9000-U+0D9FFF", "NFD U+0DA000-U+0DAFFF", "NFD U+0DB000-U+0DBFFF", "NFD U+0DC000-U+0DCFFF", "NFD U+0DD000-U+0DDFFF", "NFD U+0DE000-U+0DEFFF", "NFD U+0DF000-U+0DFFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 851968 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
